with prev_events as (select *, lag(txn_time) over (partition by txn_type order by txn_time, id) as prev_txn_time from transactions), with_gaps as (select *, case when prev_txn_time is null or txn_time > prev_txn_time + interval 14 days then 1 else 0 end as new_group_flag from prev_events), sessionized as (select id, account_id, txn_type, txn_time, merchant, sum(new_group_flag) over (partition by txn_type order by txn_time, id rows between unbounded preceding and current row) as session_no from with_gaps) select s.id, s.account_id, s.txn_type, s.txn_time, s.merchant, s.session_no, (select max(t2.amount) from transactions t2 where t2.account_id = s.account_id) as max_transaction_amount from sessionized s
